import{_ as r,o as t,c as a,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2022Q1 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2022Q1 Ceph社区季度进展报告","date":"2022-03-01T00:00:00.000Z","updated":"2022-03-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/2022Q1_Ceph社区季度总结.md","filePath":"posts/2022/2022Q1_Ceph社区季度总结.md","lastUpdated":1780460162000}'),h={name:"posts/2022/2022Q1_Ceph社区季度总结.md"};function i(n,e,p,s,l,m){return t(),a("div",null,[...e[0]||(e[0]=[o('<p>我将基于这25篇会议总结材料，生成一份2022Q1的Ceph社区季度进展报告。</p><h1 id="ceph-社区季度进展报告-—-2022-q1" tabindex="-1">Ceph 社区季度进展报告 — 2022 Q1 <a class="header-anchor" href="#ceph-社区季度进展报告-—-2022-q1" aria-label="Permalink to &quot;Ceph 社区季度进展报告 — 2022 Q1&quot;">​</a></h1><hr><h2 id="_1-本季度重点议题" tabindex="-1">1. 本季度重点议题 <a class="header-anchor" href="#_1-本季度重点议题" aria-label="Permalink to &quot;1. 本季度重点议题&quot;">​</a></h2><p>本季度 Ceph 社区的讨论高度集中在以下几个方向：</p><p><strong>Quincy 版本发布准备</strong> Quincy 是本季度最核心的主线任务。从特性冻结时间的确认、各组件的回溯（backport）策略，到最终的性能测试验证，贯穿整个季度。详见 <a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-01-11.html">Ceph Orchestrator Meeting 2022-01-11</a>) 和 <a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-01-13.html">Ceph Performance Meeting 2022-01-13</a>)。</p><p><strong>Orchestrator 稳定性与功能完善</strong> cephadm/Orchestrator 模块在本季度经历了密集的 bug 修复和功能补全，涵盖 SSH 超时、离线主机检测、NFS 高可用、服务 CPU/内存限制等多个方向。</p><p><strong>性能回归追踪</strong> Quincy 与 Pacific 的性能对比测试暴露了多处回归，尤其是 BlueStore AVL 分配器相关的写入性能问题，成为性能团队本季度的核心攻关点。</p><p><strong>指标收集架构重</strong> Ceph Manager 的Prometheus 指标收集在大规模集群下存在严重瓶颈，社区开始讨论将指标导出从 Manager 中解耦的长期方案。详见 <a href="/VideoSummary/posts/2022/Ceph_Developer_Monthly_2022-02-02.html">Ceph Developer Monthly 2022-02</a>)。</p><hr><h2 id="_2-技术亮点" tabindex="-1">2. 技术亮点 <a class="header-anchor" href="#_2-技术亮点" aria-label="Permalink to &quot;2. 技术亮点&quot;">​</a></h2><h3 id="orchestrator-cephadm" tabindex="-1">Orchestrator / cephadm <a class="header-anchor" href="#orchestrator-cephadm" aria-label="Permalink to &quot;Orchestrator / cephadm&quot;">​</a></h3><ul><li><p><strong>SSH 超时与离线主机检测</strong>：引入 cephadm 超时参数，设置可配置的默认超时时间（约 20 分钟），超时后触发健康警告。同时探索通过 agent 快速心跳检测替代 SSH 轮询，减少对 SSH 的依赖。详见 <a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-01-25.html">Ceph Orchestrator Meeting 2022-01-25</a>)。</p></li><li><p><strong>服务 CPU/内存限制</strong>：在服务规范（service spec）中引入 CPU 和内存限制属性，支持对每个服务独立设置资源上限。详见 <a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-01-04.html">Ceph Orchestrator Meeting 2022-01-04</a>)。</p></li><li><p><strong>NFS 高可用性</strong>：测试验证了 NFS daemon 在节点离线后能够重新调度，恢复时间约 1-2 分钟。同时讨论了多 NFS daemon 共存的端口冲突解决方案，以及通过 agent 加速心跳检测的优化方向。详见 <a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-03-22.html">Ceph Orchestrator Meeting 2022-03-22</a>)。</p></li><li><p><strong>NFS Manager 模块解耦</strong>：移除 NFS 导出命令对 Orchestration 模块的强依赖，使 Rook 等场景可以在不启用 Orchestrator 的情况下管理 NFS 导出。详见 <a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-02-01.html">Ceph Orchestrator Meeting 2022-02-01</a>)。</p></li><li><p><strong>外部 Prometheus 支持</strong>：开发新端点，允许外部 Prometheus 实例动态获取 Ceph 集群的监控配置，不再依赖静态配置文件。详见 <a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-03-15.html">Ceph Orchestrator Meeting 2022-03-15</a>)。</p></li><li><p><strong>升级粒度控制</strong>：实现按主机（per-host）和按 daemon 类型（per-daemon-type）的升级选项，满足大型集群用户对升级过程精细控制的需求。详见 <a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-02-07.html">Ceph Orchestrator Meeting 2022-02-07</a>)。</p></li></ul><h3 id="性能优化" tabindex="-1">性能优化 <a class="header-anchor" href="#性能优化" aria-label="Permalink to &quot;性能优化&quot;">​</a></h3><ul><li><p><strong>BlueStore PG 日志优化</strong>：提出将 PG 日志写入缓冲区的方案，减少对 RocksDB 的写放大依赖，降低 RocksDB 资源消耗。详见 <a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-03-24.html">Ceph Performance Meeting 2022-03-24</a>)。</p></li><li><p><strong>RocksDB Tombstone 清理</strong>：针对 RGW bucket 列表场景下 RocksDB 因大量 tombstone 导致的性能退化，提出通过 TTL 定期触发 compaction 的解决方案。详见 <a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-01-27.html">Ceph Performance Meeting 2022-01-27</a>) 和 <a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-03-17.html">Ceph Performance Meeting 2022-03-17</a>)。</p></li><li><p><strong>Scrub Chunk Size优化</strong>：区分 deep scrub 和 regular的 chunk 大小配置，在优化 scrub 吞吐的同时减少对客户端请求的影响。详见 <a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-01-27.html">Ceph Performance Meeting 2022-01-27</a>)。</p></li><li><p><strong>Tracing 默认编译</strong>：将 tracing 功能默认编译进 Ceph，虽有轻微性能开销，但显著提升了用户调试便利性。详见 <a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-02-03.html">Ceph Performance Meeting 2022-02-03</a>)。</p></li><li><p><strong>Primary Balancer 重构</strong>：简化了计算 PG Up Maps 的代码逻辑，相关 PR 已合并。详见 <a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-01-13.html">Ceph Performance Meeting 2022-01-13</a>)。</p></li><li><p><strong>OpenCAS 缓存集成</strong>：Intel 工程师介绍了 OpenCAS（Linux 块层存储缓存软件）与 Ceph OSD 的集成方案，支持写通、写回等多种缓存模式，可作为 OSD 的加速层。详见 <a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-03-03.html">Ceph Performance Meeting 2022-03</a>)。</p></li></ul><h3 id="指标收集架构" tabindex="-1">指标收集架构 <a class="header-anchor" href="#指标收集架构" aria-label="Permalink to &quot;指标收集架构&quot;">​</a></h3><ul><li><strong>Manager 指标瓶颈</strong>：在大型集群中，Ceph Manager 每秒需处理约 50MB 指标数据，成为显著瓶颈。社区提出短期方案（减少导出指标数量）和长期方案（per-node 或 per-daemon 独立 exporter，绕过 Manager 直接推送 Prometheus）。详见 <a href="/VideoSummary/posts/2022/Ceph_Developer_Monthly_2022-02-02.html">Ceph Developer Monthly 2022-02-02</a>)。</li></ul><hr><h2 id="_3-重要决策与里程碑" tabindex="-1">3. 重要决策与里程碑 <a class="header-anchor" href="#_3-重要决策与里程碑" aria-label="Permalink to &quot;3. 重要决策与里程碑&quot;">​</a></h2><p><strong>Quincy 特性冻结</strong> 本季度初确认了 Quincy 版本的特性冻结节点，self-adm 二进制文件重构被列为冻结前必须完成的工作。Rook Manager Module 因尚未完成测试，不纳入 Quincy 初始版本。详见 <a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-01-11.html">Ceph Orchestrator Meeting 2022-01-11</a>)。</p><p><strong>Rook 定位讨论</strong> 社区就 Rook Manager Module 的长期定位进行了深入讨论。核心结论是：Kubernetes 环境下 Rook 的操作模式与 cephadm 存在根本差异，部分 Orchestrator API 对 Rook 并不适用，需要为 Rook 设计独立的 API 或调整文档定位。详见 <a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-02-15.html">Ceph Orchestrator Meeting 2022-02-15</a>)。</p><p><strong>版本降级策略</strong> 讨论了 minor 版本降级支持的可行性，结论是当前实现存在迁移处理和升级状态等问题，建议在新 major 版本中通过强制标志（force flag）重新实现降级支持，并在 minor 版本发布前进行专项测试。详见 <a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-03-08.html">Ceph Orchestrator Meeting 2022-03-08</a>)。</p><p><strong>AVL 分配器性能回归确认</strong> 通过二分法定位到 Quincy 中写入性能回归的根因：AVL 分配器的行为变更（First Fit vs Best Fit 模式切换）。团队决定测试回滚该变更的效果，并评估是否在发布前修复。详见 <a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-03-31.html">Ceph Performance Meeting 2022-03-31</a>)。</p><p><strong>Teuthology 本地化</strong> 决定推进 Teuthology 的容器化本地部署方案，使用 Docker Compose 自动化安装过程，降低外部贡献者的参与门槛。详见 <a href="./2022-03-24_-Ceph_Tech_Talk_-_Running_Teuthology_Locally.html">2022-03-24 Ceph Tech Talk - Running Teuthology Locally</a>。</p><hr><h2 id="_4-社区动态" tabindex="-1">4. 社区动态 <a class="header-anchor" href="#_4-社区动态" aria-label="Permalink to &quot;4. 社区动态&quot;">​</a></h2><p><strong>团队变动</strong> Sebastian 于 1 月底离开 Red Hat，Adam 接手 Orchestrator 周会的主持工作。详见 <a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-01-18.html">Ceph Orchestrator Meeting 2022-01-18</a>)。</p><p><strong>Science Working Group</strong> 科学计算工作组本季度新增了来自 GWDG（管理约 7PB 存储，计划扩容至 19PB+）和 Flatiron Institute（单集群约 30PB）的成员。会议讨论了大规模集群中的 BlueStore corruption、快照性能、元数据瓶颈等实际运维问题，并提及即将举行的 Cephalocon 会议。详见 <a href="/VideoSummary/posts/2022/Ceph_Science_Working_Group_2022-01-26.html">Ceph Science Working Group 2022-01-26</a>)。</p><p><strong>Cephadm 开发者文档</strong> 社区启动了 cephadm 开发者文档项目，计划覆盖重要数据结构、服务循环机制、Monkey Store 存储格式、Manager 故障转移持久化等内部实现细节，面向开发者而非最终用户。详见 <a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-03-01.html">Ceph Orchestrator Meeting 2022-03-01</a>)。</p><p><strong>Quincy 性能测试</strong> 性能团队在本季度使用包含 975 个 OSD 的大规模集群进行了 Quincy 版本的系统性能测试，覆盖 RBD、RGW、iSCSI、NBD 等多种工作负载，并引入了新的恢复测试方法（使用独立池和 fio 模拟 OSD 故障恢复）。详见 <a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-01-13.html">Ceph Performance Meeting 2022-01-13</a>) 和 <a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-01-20.html">Ceph Performance Meeting 2022-01-20</a>)。</p><p><strong>MClock 配置测试</strong> 计划在 Giba 集群上使用 CBT 对 MClock 的三种配置文件（高客户端 IO、高恢复操作、平衡）进行系统性测试，评估其对 scrubing 和恢复操作的影响。详见 <a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-02-03.html">Ceph Performance Meeting 2022-02-03</a>)。</p><hr><h2 id="_5-下季度展望" tabindex="-1">5. 下季度展望 <a class="header-anchor" href="#_5-下季度展望" aria-label="Permalink to &quot;5. 下季度展望&quot;">​</a></h2><p>基于本季度的讨论内容，预计 2022 Q2 将重点推进以下方向：</p><ol><li><p><strong>Quincy 正式发布</strong>：本季度已完成特性冻结和大规模性能测试，Q2 预计将完成最终验证并正式发布 Quincy 版本，同时推进对 Pacific 的backport 工作。</p></li><li><p><strong>AVL 分配器修复</strong>：BlueStore 写入性能回归问题已定位到 AVL 分配器，Q2 将完成修复验证并决定是否纳入 Quincy 发布版本或作为后续 patch。</p></li><li><p><strong>cephadm Agent 功能扩展</strong>：本季度已规划了 agent 替代 SSH 的完整功能列表，Q2 将推进 agent 在部署、管理、心跳检测等场景的能力建设，逐步减少对 SSH 的依赖。</p></li><li><p><strong>指标收集架构演进</strong>：Manager 指标瓶颈的长期解决方案（per-daemon exporter）已完成原型设计讨论，Q2 预计进入实验性实现阶段。</p></li><li><p><strong>Rook 集成方向明确</strong>：社区已识别 Rook 与 cephadm 的架构差异，Q2 将通过专项会议（含 Dashboard 团队和 Rook 团队）明确 Rook Manager Module 的最终定位和 API 设计方向。</p></li><li><p><strong>PG 日志优化落地</strong>：将 PG 日志写入缓冲区、减少 RocksDB 依赖的方案已进入讨论阶段，Q2 预计推进具体实现。</p></li></ol><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2022/2022-03-24_-_-_Ceph_Tech_Talk_-_Running_Teuthology_Locally.html">2022-03-24 :: Ceph Tech Talk - Running Teuthology Locally</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Developer_Monthly_2022-02-02.html">Ceph Developer Monthly 2022-02-02</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-01-04.html">Ceph Orchestrator Meeting 2022-01-04</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-01-11.html">Ceph Orchestrator Meeting 2022-01-11</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-01-18.html">Ceph Orchestrator Meeting 2022-01-18</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-01-25.html">Ceph Orchestrator Meeting 2022-01-25</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-02-01.html">Ceph Orchestrator Meeting 2022-02-01</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-02-07.html">Ceph Orchestrator Meeting 2022-02-07</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-02-15.html">Ceph Orchestrator Meeting 2022-02-15</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-02-22.html">Ceph Orchestrator Meeting 2022-02-22</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-03-01.html">Ceph Orchestrator Meeting 2022-03-01</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-03-08.html">Ceph Orchestrator Meeting 2022-03-08</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-03-15.html">Ceph Orchestrator Meeting 2022-03-15</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-03-22.html">Ceph Orchestrator Meeting 2022-03-22</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Orchestrator_Meeting_2022-03-29.html">Ceph Orchestrator Meeting 2022-03-29</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-01-06.html">Ceph Performance Meeting 2022-01-06</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-01-13.html">Ceph Performance Meeting 2022-01-13</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-01-20.html">Ceph Performance Meeting 2022-01-20</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-01-27.html">Ceph Performance Meeting 2022-01-27</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-02-03.html">Ceph Performance Meeting 2022-02-03</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-03-03.html">Ceph Performance Meeting 2022-03-03</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-03-17.html">Ceph Performance Meeting 2022-03-17</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-03-24.html">Ceph Performance Meeting 2022-03-24</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Performance_Meeting_2022-03-31.html">Ceph Performance Meeting 2022-03-31</a>)</li><li><a href="/VideoSummary/posts/2022/Ceph_Science_Working_Group_2022-01-26.html">Ceph Science Working Group 2022-01-26</a>)</li></ul>',38)])])}const g=r(h,[["render",i]]);export{c as __pageData,g as default};
